import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"LangGraph.js API 索引","description":"按包与 API 家族速查本手册 Workflow 篇实际讲过的 LangGraph.js 入口、签名直觉与正文链接。","frontmatter":{"title":"LangGraph.js API 索引","description":"按包与 API 家族速查本手册 Workflow 篇实际讲过的 LangGraph.js 入口、签名直觉与正文链接。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/api-index/langgraph-api-index.md","filePath":"ts-ai/appendix/api-index/langgraph-api-index.md","lastUpdated":1786166505000}'),r={name:"ts-ai/appendix/api-index/langgraph-api-index.md"};function c(n,t,i,h,s,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="langgraph-js-api-索引" tabindex="-1">LangGraph.js API 索引 <a class="header-anchor" href="#langgraph-js-api-索引" aria-label="Permalink to &quot;LangGraph.js API 索引&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本索引帮助你从类名/方法名跳回正文。条目只收录 <code>docs/ts-ai/workflow</code>（及 Agent 边界对照中点名的图语义）已展开的 API；不复制教程或大段示例。</p><h2 id="_1-索引范围与排除" tabindex="-1">1. 索引范围与排除 <a class="header-anchor" href="#_1-索引范围与排除" aria-label="Permalink to &quot;1. 索引范围与排除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包含</th><th>排除</th></tr></thead><tbody><tr><td><code>@langchain/langgraph</code>、Checkpointer 包、supervisor/swarm 预构建入口中本手册讲过的 API</td><td>未在正文出现的冷门导出、Python <code>langgraph</code> API 百科</td></tr><tr><td><code>StateGraph</code>、State/Reducer、边路由、<code>Send</code>、Checkpoint/Store 边界、<code>interrupt</code>/<code>Command</code>、多 Agent 进阶入口</td><td>完整 HITL 产品流程、队列 Worker 实现细节、记忆产品语义全文</td></tr><tr><td>调用配置（<code>thread_id</code>、<code>recursionLimit</code>）、常见错误与事件观察方式</td><td>NestJS/BullMQ/SSE 协议；<code>createAgent</code> 全量 Runtime（见 <a href="/ts-ai/appendix/api-index/langchain-api-index">LangChain.js API 索引</a>）</td></tr></tbody></table><p>先确认问题属于「图控制流 / 持久执行 / 多 Agent」，再进对应家族。</p><h2 id="_2-包与入口对象" tabindex="-1">2. 包与入口对象 <a class="header-anchor" href="#_2-包与入口对象" aria-label="Permalink to &quot;2. 包与入口对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包 / 模块</th><th>本手册常用入口</th><th>正文</th></tr></thead><tbody><tr><td><code>@langchain/langgraph</code></td><td><code>Annotation</code>、<code>StateGraph</code>、<code>START</code>、<code>END</code>、<code>messagesStateReducer</code>、<code>Send</code>、<code>interrupt</code>、<code>Command</code>、<code>MemorySaver</code></td><td><a href="/ts-ai/workflow/langgraph-core/state-graph">StateGraph</a>、<a href="/ts-ai/workflow/durable-execution/checkpoint-store">Checkpoint</a>、<a href="/ts-ai/workflow/durable-execution/interrupt-command">Interrupt</a></td></tr><tr><td><code>@langchain/langgraph/prebuilt</code></td><td><code>createReactAgent</code>（<strong>遗留 / prebuilt</strong>；仅 supervisor/swarm 官方示意，<strong>非</strong>手册主线 Agent API）</td><td><a href="/ts-ai/workflow/multi-agent/supervisor-handoff">Supervisor 与 Handoff</a>、<a href="/ts-ai/workflow/multi-agent/network-swarm">Network / Swarm</a>；主线见 <a href="/ts-ai/agent/runtime/create-agent">createAgent</a></td></tr><tr><td><code>@langchain/langgraph-checkpoint-postgres</code></td><td><code>PostgresSaver</code></td><td><a href="/ts-ai/workflow/durable-execution/checkpoint-store">图持久化：Checkpointer 与 Checkpoint</a></td></tr><tr><td><code>@langchain/langgraph-supervisor</code></td><td><code>createSupervisor</code>、<code>createHandoffTool</code></td><td><a href="/ts-ai/workflow/multi-agent/supervisor-handoff">Supervisor 与 Handoff</a></td></tr><tr><td><code>@langchain/langgraph-swarm</code></td><td><code>createSwarm</code>、<code>createHandoffTool</code></td><td><a href="/ts-ai/workflow/multi-agent/network-swarm">Network / Swarm</a></td></tr></tbody></table><p>工作流原则与何时不用图：见 <a href="/ts-ai/workflow/workflow-foundations/workflow-principles-boundaries">工作流原则与边界</a>。记忆侧 Store 产品语义见 <a href="/ts-ai/knowledge/memory/checkpoint-store">记忆视角：Checkpoint 与 Store</a>。</p><h2 id="_3-核心-api-家族" tabindex="-1">3. 核心 API 家族 <a class="header-anchor" href="#_3-核心-api-家族" aria-label="Permalink to &quot;3. 核心 API 家族&quot;">​</a></h2><h3 id="_3-1-stategraph-state-reducer" tabindex="-1">3.1 <code>StateGraph</code> / State / Reducer <a class="header-anchor" href="#_3-1-stategraph-state-reducer" aria-label="Permalink to &quot;3.1 `StateGraph` / State / Reducer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>Annotation</code> / <code>Annotation.Root</code></td><td>声明 State 通道类型、可选 <code>reducer</code> / <code>default</code></td><td><code>Annotation.Root({ field: Annotation&lt;T&gt;({ reducer?, default? }) })</code></td><td><a href="/ts-ai/workflow/langgraph-core/state-graph">StateGraph</a>、<a href="/ts-ai/workflow/langgraph-core/state-reducers">State 与 Reducer</a></td></tr><tr><td>默认覆盖语义</td><td>未配 reducer 时后到更新覆盖通道值</td><td>标量业务字段（<code>status</code>、<code>category</code>）常用</td><td><a href="/ts-ai/workflow/langgraph-core/state-reducers">State 与 Reducer</a></td></tr><tr><td><code>reducer</code></td><td><code>(current, update) =&gt; next</code> 合并并发/增量更新</td><td>追加用 <code>concat</code>；计数节点应返回<strong>增量</strong></td><td>同上</td></tr><tr><td><code>messagesStateReducer</code></td><td>消息列表追加，并处理同 <code>id</code> 替换等约定</td><td><code>Annotation&lt;BaseMessage[]&gt;({ reducer: messagesStateReducer, default: () =&gt; [] })</code></td><td>同上</td></tr><tr><td><code>StateGraph</code></td><td>声明式状态图构建器</td><td><code>new StateGraph(State).addNode(…).addEdge(…).compile()</code></td><td><a href="/ts-ai/workflow/langgraph-core/state-graph">StateGraph</a></td></tr><tr><td><code>compile</code></td><td>得到可 <code>invoke</code> / <code>stream</code> 的图；可注入 checkpointer</td><td><code>compile({ checkpointer? })</code>；编译后勿再改拓扑</td><td>同上；最小骨架见 <a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小 StateGraph</a></td></tr><tr><td><code>graph.invoke</code></td><td>跑完整路径，返回最终 State</td><td><code>invoke(input, { configurable?, recursionLimit? })</code>；带 default 的通道可省略</td><td><a href="/ts-ai/workflow/langgraph-core/state-graph">StateGraph</a></td></tr><tr><td><code>graph.stream</code></td><td>按节点（或配置）产出状态更新轨迹</td><td>默认可对照「节点 → 通道变化」；子图可开 <code>subgraphs: true</code></td><td>同上；<a href="/ts-ai/workflow/langgraph-core/subgraphs">Subgraphs</a></td></tr></tbody></table><p>建模（通道表 + 路径表）先于编码：见 <a href="/ts-ai/workflow/langgraph-core/workflow-modeling">工作流建模</a>。</p><h3 id="_3-2-node、edge-与路由" tabindex="-1">3.2 Node、Edge 与路由 <a class="header-anchor" href="#_3-2-node、edge-与路由" aria-label="Permalink to &quot;3.2 Node、Edge 与路由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>addNode</code></td><td>注册节点函数：读 State，返回部分更新</td><td><code>addNode(name, async (state) =&gt; partialUpdate)</code></td><td><a href="/ts-ai/workflow/langgraph-core/nodes-edges-routing">Node、Edge 与条件路由</a></td></tr><tr><td><code>addEdge</code></td><td>固定边；常用入口/出口哨兵</td><td><code>addEdge(START, &quot;a&quot;)</code> / <code>addEdge(&quot;b&quot;, END)</code></td><td>同上</td></tr><tr><td><code>START</code> / <code>END</code></td><td>图级入口与终止哨兵（不是业务节点）</td><td>条件路由也可 <code>return END</code> 早停</td><td>同上；原则见 <a href="/ts-ai/workflow/workflow-foundations/workflow-principles-boundaries">工作流原则</a></td></tr><tr><td><code>addConditionalEdges</code></td><td>按 State 选择后继；必须穷尽或显式 fallback</td><td>路径函数返回已注册节点名、<code>END</code>、名称数组，或 <code>Send[]</code></td><td><a href="/ts-ai/workflow/langgraph-core/nodes-edges-routing">节点与路由</a></td></tr><tr><td><code>Send</code></td><td>动态扇出：为每个工作项调度目标节点并带载荷</td><td><code>new Send(nodeName, payload)</code>；空列表需显式 <code>END</code>/fallback</td><td><a href="/ts-ai/workflow/langgraph-core/loops-parallelism-aggregation">循环、并行与结果汇聚</a></td></tr><tr><td>循环预算 + <code>recursionLimit</code></td><td>业务优雅停 vs 框架防失控</td><td>State 写 <code>attempts</code>/<code>status</code>；调用侧 <code>{ recursionLimit }</code></td><td>同上；测试见 <a href="/ts-ai/workflow/workflow-quality/graph-testing">图测试</a></td></tr><tr><td>子图 <code>addNode</code> / 映射 <code>invoke</code></td><td>复用编译子图，或在节点内映射 Schema 后调用</td><td>先 <code>compile</code> 子图再挂父图；错误可冒泡或 catch 后有边到 <code>END</code></td><td><a href="/ts-ai/workflow/langgraph-core/subgraphs">Subgraphs</a></td></tr></tbody></table><h3 id="_3-3-checkpoint-store" tabindex="-1">3.3 Checkpoint / Store <a class="header-anchor" href="#_3-3-checkpoint-store" aria-label="Permalink to &quot;3.3 Checkpoint / Store&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td>Checkpointer（概念）</td><td>在 Super-step 边界读写图快照，支撑续跑与 Interrupt</td><td><code>compile({ checkpointer })</code></td><td><a href="/ts-ai/workflow/durable-execution/checkpoint-store">图持久化：Checkpointer 与 Checkpoint</a></td></tr><tr><td><code>configurable.thread_id</code></td><td>标识同一执行线程；相同 id 加载最新 Checkpoint</td><td><code>{ configurable: { thread_id } }</code>；服务端生成/校验</td><td>同上</td></tr><tr><td><code>configurable.checkpoint_id</code></td><td>钉在历史快照上（排障/受控分叉）</td><td>通常来自 <code>getStateHistory</code>；生产支付线程勿随意时间旅行</td><td>同上；<a href="/ts-ai/workflow/durable-execution/state-version-migration">状态版本迁移</a></td></tr><tr><td><code>MemorySaver</code></td><td>进程内 Checkpointer，开发/单测用</td><td><code>new MemorySaver()</code>；重启即失，不能证明跨天 HITL</td><td><a href="/ts-ai/workflow/durable-execution/checkpoint-store">图持久化：Checkpointer 与 Checkpoint</a></td></tr><tr><td><code>PostgresSaver</code></td><td>生产持久 Checkpointer</td><td><code>PostgresSaver.fromConnString(url)</code> → <code>await setup()</code> → <code>compile({ checkpointer })</code></td><td>同上</td></tr><tr><td><code>getState</code></td><td>读当前线程快照：<code>values</code> / <code>next</code> / <code>tasks</code></td><td><code>await graph.getState(config)</code></td><td>同上；Interrupt 观察见下节</td></tr><tr><td><code>getStateHistory</code></td><td>遍历历史 Checkpoint</td><td><code>for await (const h of graph.getStateHistory(config))</code></td><td>同上</td></tr><tr><td><code>updateState</code></td><td>写入新 Checkpoint（迁移、运维校正）</td><td><code>await graph.updateState(config, partial)</code>；保留历史便于审计</td><td><a href="/ts-ai/workflow/durable-execution/state-version-migration">状态版本迁移</a></td></tr><tr><td>Store（边界）</td><td>跨线程 KV；<strong>不是</strong>执行游标</td><td>偏好/事实复用归记忆篇；权威真相归业务 DB</td><td><a href="/ts-ai/workflow/durable-execution/checkpoint-store">图持久化：Checkpointer 与 Checkpoint</a></td></tr></tbody></table><h3 id="_3-4-interrupt-command-恢复" tabindex="-1">3.4 <code>interrupt</code> / Command / 恢复 <a class="header-anchor" href="#_3-4-interrupt-command-恢复" aria-label="Permalink to &quot;3.4 `interrupt` / Command / 恢复&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>interrupt(value)</code></td><td>节点内暂停并把 payload 暴露给调用方</td><td><code>const decision = interrupt(payload)</code>；首次抛 <code>GraphInterrupt</code>，Resume 后返回 resume 值</td><td><a href="/ts-ai/workflow/durable-execution/interrupt-command">Interrupt 与 Command</a></td></tr><tr><td><code>GraphInterrupt</code></td><td>Interrupt 传播用的特殊错误</td><td><code>try/catch</code> 捕获后必须重新抛出，否则暂停失效</td><td>同上</td></tr><tr><td><code>interrupt_before</code> / <code>interrupt_after</code></td><td>编译期静态断点（调试）</td><td>与节点内动态 <code>interrupt</code> 区分</td><td>同上</td></tr><tr><td><code>result.__interrupt__</code></td><td><code>invoke</code> 结果中读取挂起 payload</td><td><code>pending.value</code> 对应 <code>interrupt</code> 入参</td><td>同上</td></tr><tr><td><code>Command({ resume })</code></td><td>恢复 Interrupt，把值送回 <code>interrupt()</code></td><td><code>invoke(new Command({ resume }), 同一 thread_id)</code>；勿用普通对象假装恢复</td><td>同上</td></tr><tr><td><code>Command({ update, goto })</code></td><td>节点返回时更新 State 并路由（控制流）</td><td>与 invoke 侧 <code>resume</code> 用途不同</td><td>同上</td></tr><tr><td>产品层暂停策略</td><td>超时、拒绝、身份、重复点击、废弃线程</td><td>API 原语之上的状态机；业务表存审批，不只靠 <code>getState</code></td><td><a href="/ts-ai/workflow/durable-execution/pause-resume">暂停与恢复</a></td></tr></tbody></table><p>Resume 会重放中断节点：副作用必须幂等；见 <a href="/ts-ai/workflow/durable-execution/idempotency-replay">幂等与重放</a>。</p><h3 id="_3-5-多-agent-相关入口-进阶" tabindex="-1">3.5 多 Agent 相关入口（进阶） <a class="header-anchor" href="#_3-5-多-agent-相关入口-进阶" aria-label="Permalink to &quot;3.5 多 Agent 相关入口（进阶）&quot;">​</a></h3><p>仅在单图 + Checkpoint/Interrupt 基线已稳定，且单 Agent/单图证明不足后再用。包版本敏感，以官方 README 与正文示意为准。</p><p><strong>Agent 工厂边界：</strong> 本手册默认 Agent API 是 <code>langchain</code> 的 <a href="/ts-ai/agent/runtime/create-agent"><code>createAgent</code></a>。<code>createReactAgent</code> 只作为 supervisor/swarm 历史官方示意中的 <strong>LangGraph prebuilt / 版本敏感遗留入口</strong>收录；生产优先 <code>createAgent</code> 基线，再按官方包是否接受该产物决定是否钉版本沿用 prebuilt——勿静默互换。</p><table tabindex="0"><thead><tr><th>API</th><th>用途（一句话）</th><th>签名直觉</th><th>正文</th></tr></thead><tbody><tr><td><code>createReactAgent</code></td><td><strong>遗留 / prebuilt</strong> ReAct 工厂；多 Agent 官方示意常用，<strong>不是</strong>手册主线 Agent API（主线为 <code>createAgent</code>）</td><td><code>createReactAgent({ llm, tools, name?, prompt? })</code>；职责对照 <code>createAgent</code> 的 <code>model</code>/<code>tools</code>/<code>systemPrompt</code></td><td><a href="/ts-ai/workflow/multi-agent/supervisor-handoff">Supervisor 与 Handoff</a>、<a href="/ts-ai/workflow/multi-agent/network-swarm">Network / Swarm</a></td></tr><tr><td><code>createSupervisor</code></td><td>中心委派：Supervisor 转交 Worker，控制权可回中心</td><td><code>createSupervisor({ agents, llm, prompt }).compile({ checkpointer })</code>；<code>agents</code> 类型以官方包为准</td><td>同上</td></tr><tr><td><code>createHandoffTool</code></td><td>转移会话控制权（<code>active_agent</code> 变更）</td><td><code>createHandoffTool({ agentName, description })</code>；名称须稳定唯一</td><td>同上；Swarm 变体见 <a href="/ts-ai/workflow/multi-agent/network-swarm">Network / Swarm</a></td></tr><tr><td><code>createSwarm</code></td><td>对等/网络式多 Agent，跟踪 <code>activeAgent</code></td><td><code>createSwarm({ agents, … })</code>；官方示意常与 <code>createReactAgent</code> 搭配（版本敏感）</td><td><a href="/ts-ai/workflow/multi-agent/network-swarm">Network / Swarm</a></td></tr><tr><td>Deep Agents / <code>task</code> Subagent</td><td>工具式委派 + 上下文隔离的长任务形态（可选）</td><td>不是默认升级；权限命中 <code>interrupt</code> 应真暂停</td><td><a href="/ts-ai/workflow/multi-agent/deep-agents">Deep Agents</a></td></tr><tr><td>节点内 <code>createAgent</code> / 子图</td><td>手册主线：把 Agent 当节点能力，控制流仍由边拥有</td><td>组装清单：控制流归图，推理归 <code>createAgent</code></td><td><a href="/ts-ai/workflow/assembly/assembly-recipes-checklist">Workflow 组装清单</a>；<a href="/ts-ai/agent/runtime/create-agent">createAgent</a></td></tr></tbody></table><h2 id="_4-事件、错误与配置速查" tabindex="-1">4. 事件、错误与配置速查 <a class="header-anchor" href="#_4-事件、错误与配置速查" aria-label="Permalink to &quot;4. 事件、错误与配置速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>关键项</th><th>放哪里处理</th><th>正文</th></tr></thead><tbody><tr><td>逐步观察</td><td><code>stream</code> 节点更新；可选 <code>subgraphs: true</code></td><td>对照通道变化与路由</td><td><a href="/ts-ai/workflow/langgraph-core/state-graph">StateGraph</a>、<a href="/ts-ai/workflow/workflow-quality/trace-visualization">Trace 可视化</a></td></tr><tr><td>线程配置</td><td><code>configurable.thread_id</code> / <code>checkpoint_id</code></td><td>每次续跑/Resume 同一线程；分叉慎用</td><td><a href="/ts-ai/workflow/durable-execution/checkpoint-store">Checkpoint</a></td></tr><tr><td>循环护栏</td><td><code>recursionLimit</code>；业务 <code>attempts</code> + <code>END</code></td><td>框架抛错防失控；业务写优雅终态</td><td><a href="/ts-ai/workflow/langgraph-core/loops-parallelism-aggregation">循环与并行</a></td></tr><tr><td>路由错误</td><td>条件边返回未注册名、漏映射、到不了 <code>END</code></td><td>穷尽映射或显式 reject/<code>END</code>；测试断言路径</td><td><a href="/ts-ai/workflow/langgraph-core/nodes-edges-routing">节点与路由</a>、<a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小骨架</a></td></tr><tr><td>Reducer 错误</td><td>并行丢更新、messages 手写 concat 错乱</td><td>正确 reducer / <code>messagesStateReducer</code></td><td><a href="/ts-ai/workflow/langgraph-core/state-reducers">State 与 Reducer</a></td></tr><tr><td>Interrupt 失效</td><td>无 checkpointer、无 <code>thread_id</code>、吞掉 <code>GraphInterrupt</code>、用裸对象 resume</td><td>补齐三者 + <code>Command({ resume })</code></td><td><a href="/ts-ai/workflow/durable-execution/interrupt-command">Interrupt 与 Command</a></td></tr><tr><td>持久化误用</td><td>生产用 <code>MemorySaver</code>；把订单真相只写 Checkpoint</td><td>换 <code>PostgresSaver</code>；权威数据回源业务 DB</td><td><a href="/ts-ai/workflow/durable-execution/checkpoint-store">Checkpoint</a></td></tr><tr><td>重放双执行</td><td><code>interrupt</code> 前副作用无幂等键</td><td>幂等键 + 副作用后置</td><td><a href="/ts-ai/workflow/durable-execution/idempotency-replay">幂等与重放</a></td></tr><tr><td>版本不兼容</td><td>旧 Checkpoint 对上新图/新 State 形状</td><td>Resume 前 <code>getState</code> → 迁移/<code>updateState</code> 或新开线程</td><td><a href="/ts-ai/workflow/durable-execution/state-version-migration">状态版本迁移</a>、<a href="/ts-ai/workflow/workflow-quality/workflow-release-compatibility">发布兼容</a></td></tr></tbody></table><h2 id="_5-关联章节" tabindex="-1">5. 关联章节 <a class="header-anchor" href="#_5-关联章节" aria-label="Permalink to &quot;5. 关联章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>用本索引时怎么用</th></tr></thead><tbody><tr><td><a href="/ts-ai/workflow/">工作流总览</a></td><td>原则 → 核心图 → 持久执行 → 多 Agent → 质量</td></tr><tr><td><a href="/ts-ai/workflow/workflow-foundations/">工作流基础</a></td><td>边界与最小可跑骨架</td></tr><tr><td><a href="/ts-ai/workflow/langgraph-core/">LangGraph 核心</a></td><td>StateGraph、Reducer、路由、循环/<code>Send</code>、Subgraph</td></tr><tr><td><a href="/ts-ai/workflow/durable-execution/">持久执行</a></td><td>Checkpoint、Interrupt、暂停恢复、幂等、迁移</td></tr><tr><td><a href="/ts-ai/workflow/multi-agent/">多 Agent</a></td><td>Supervisor、Swarm、Deep Agents（进阶）</td></tr><tr><td><a href="/ts-ai/workflow/workflow-quality/">工作流质量</a></td><td>图测试、状态转移、Trace、发布兼容</td></tr><tr><td><a href="/ts-ai/workflow/assembly/assembly-recipes-checklist">Workflow 组装清单</a></td><td>配方验收与 Checkpointer/<code>Command</code> 清单</td></tr><tr><td><a href="/ts-ai/appendix/references/official-resources">官方资料索引</a></td><td>本索引未收录的 API，以官方文档为准</td></tr><tr><td><a href="/ts-ai/appendix/api-index/langchain-api-index">LangChain.js API 索引</a></td><td>ChatModel、<code>tool</code>、<code>createAgent</code>、Runnable</td></tr><tr><td><a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a></td><td>行为验收勾选</td></tr></tbody></table>',28)])])}const u=e(r,[["render",c]]);export{g as __pageData,u as default};
